@php
    $categoryLabels = ['General' => 'General election', 'Faculty Rep' => 'Faculty representatives', 'Hostel Rep' => 'Hostel representatives', 'Lga Rep' => 'LGA representatives'];
    $selectedCategory = $electionCategory ?? 'all';
    $filters = $electionFilters ?? ['office' => 'all', 'entity' => 'all', 'status' => 'all', 'search' => ''];
    $query = request()->query();
    $queryString = http_build_query($query);
    $categoryUrl = function ($category) use ($query) {
        $next = $query;
        if ($category === 'all') unset($next['category']); else $next['category'] = $category;
        return url('election-results') . ($next ? '?' . http_build_query($next) : '');
    };
@endphp

